import json,hashlib,re
ROOT='/Users/carmen/Desktop/星系'
D=ROOT+'/data/cache/1063b17ca65ec1b76f30e460.docs.json'
raw=open(D,'rb').read();T=json.loads(raw.decode())[0]['text']
C=json.load(open(ROOT+'/loop/state/out/read_dafeng_L2_0114.candidate.json'))
S,E=C['source']['unitRange']
def walk(o):
    if isinstance(o,dict):
        if 'quote' in o and 'start' in o and 'end' in o: yield o
        for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
bad=[];n=0
for r in walk(C):
    n+=1
    if T[r['start']:r['end']]!=r['quote']: bad.append(r['start'])
    if r['sourceHash']!=hashlib.sha256(raw).hexdigest(): bad.append('hash')
    ini=S<=r['start'] and r['end']<=E
    if ini and r.get('inUnit') is False: bad.append('wrong-inunit')
    if not ini and r.get('inUnit') is not False: bad.append('missing-inunit-flag')
print('quotes',n,'bad',bad)
